"""Build our declarative catalogue from the saved, read-only reference audit."""
import json,re,unicodedata
from pathlib import Path
root=Path(__file__).resolve().parents[1]
audit=json.loads((root/'research/bagpack-2026-10-31/observed-options.json').read_text())
def slug(s):
 return re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFKD',s.lower().replace('ł','l')).encode('ascii','ignore').decode()).strip('-')
families=[('laminated','Papier laminowany','torby-papierowe-laminowane'),('premium-kraft','Papier kraft premium','torby-papierowe-premium-eko'),('kraft','Kraft z uchwytem papierowym','torby-papierowe-eko-kraft'),('giftbox','Opakowania prezentowe','opakowania-giftbox'),('cotton','Torby bawełniane','torby-bawelniane'),('drawstring','Workoplecaki','worki-workoplecaki'),('jute','Torby jutowe','torby-z-juty')]
products=[]
for p in audit['products']:
 family=next(f[0] for f in families if any('/'+f[2]+'/' in c['url'] and any(x['url']==p['url'] for x in c['products']) for c in audit['categories']))
 fields=[]
 for s in p['selectors']:
  key={'print_type':'printMode','colors_front':'inkFront','colors_back':'inkBack','dtf_size':'dtfSize'}.get(s['name'])
  if not key:
   key=next(k for label,k in [('Rozmiar','size'),('Papier','paper'),('Druk','printing'),('Uszlachetnienie','finish'),('Kolor sznurka','cord'),('Kolor tasiemki','ribbon')] if label in s['label'])
  options=[{'id':slug(o['label']),'label':o['label']} for o in s['options'] if o['value'] and 'Wybierz opcj' not in o['label']]
  label={'size':'Format (cm)','paper':'Papier','printing':'Technika nadruku','finish':'Uszlachetnienie','cord':'Kolor sznurka','ribbon':'Kolor tasiemki','printMode':'Nadruk','inkFront':'Liczba kolorów nadruku','inkBack':'Liczba kolorów na tyle','dtfSize':'Powierzchnia nadruku DTF'}[key]
  fields.append({'id':key,'label':label,'options':options})
 lines=[l.strip() for l in (p.get('details') or '').split('\n') if l.strip()]
 specs=dict(zip(lines[::2],lines[1::2]))
 title=p['title'].replace('Torby papierowe PREMIUM eko+','Papier kraft premium').replace('Torby papierowe laminowane','Papier laminowany').replace('EKO KRAFT','kraft').replace('GiftBox rozmiar','Opakowanie prezentowe')
 dims=specs.get('Rozmiar') or (re.search(r'\d+[x×]\d+(?:[x×+]\d+)*',title.replace(' ','')) or [''])[0]
 if not dims and fields[0]['id']=='size':dims=fields[0]['options'][0]['label']
 products.append({'id':slug(p['url'].split('/produkt/')[1].strip('/')),'family':family,'name':title,'size':dims,'specs':specs,'fields':fields,'source':p['url'],'pricing':'quote','productionStatus':'requires-merchant-confirmation'})
out={'schemaVersion':1,'auditedAt':audit['checkedAt'],'families':[{'id':a,'name':b} for a,b,_ in families],'products':products}
(root/'configuration/catalog-data.js').write_text('// Generated by tools/build-bag-catalog.py. No supplier prices or stock are imported.\nexport default '+json.dumps(out,ensure_ascii=False,separators=(',',':'))+';\n')
print(len(products),'products,',sum(len(p['fields']) for p in products),'option fields')
